const cmds = [
  "find .. -name AGENTS.md -print",
  "git status --short",
  "find src/components -iname '*MessageComposer*' -o -iname '*Reply*Preview*' -o -iname '*Cancel*' | head -100",
  "cat package.json | head -100"
];
const r = await Promise.allSettled(cmds.map(cmd => tools.exec_command({cmd,workdir:"/app",yield_time_ms:10000,max_output_tokens:4000})));
r.forEach((x,i)=>text(`${cmds[i]}\n${x.status==="fulfilled"?x.value.output:String(x.reason)}`));

const cmds = [
  "sed -n '1,300p' src/components/views/rooms/MessageComposer.tsx",
  "sed -n '1,260p' src/components/views/rooms/ReplyPreview.tsx",
  "find test -iname '*MessageComposer*' -o -iname '*ReplyPreview*' -o -iname '*Profile*' | head -100",
  "grep -R -n 'mx_MessageComposer_roomReplaced\\|roomReplaced\\|ReplyPreview' res/css src/components/views/rooms test | head -160"
];
const r = await Promise.allSettled(cmds.map(cmd => tools.exec_command({cmd,workdir:"/app",yield_time_ms:10000,max_output_tokens:12000})));
r.forEach((x,i)=>text(`${cmds[i]}\n${x.status==="fulfilled"?x.value.output:String(x.reason)}`));

