import React from "react";
import { EventType } from "matrix-js-sdk/src/@types/event";

import MImageBody from "./MImageBody";
import { presentableTextForFile } from "../../../utils/FileUtils";
import { IMediaEventContent } from "../../../customisations/models/IMediaEventContent";
import SenderProfile from "./SenderProfile";
import { _t } from "../../../languageHandler";

const FORCED_IMAGE_HEIGHT = 44;

export default class MImageReplyBody extends MImageBody {
    public onClick = (ev: React.MouseEvent): void => {
        ev.preventDefault();
    };

    public wrapImage(contentUrl: string, children: JSX.Element): JSX.Element {
        return children;
    }

    // Don't show "Download this_file.png ..."
    public getFileBody(): string {
        const sticker = this.props.mxEvent.getType() === EventType.Sticker;
        return presentableTextForFile(this.props.mxEvent.getContent(), sticker ? _t("Sticker") : _t("Image"), !sticker);
    }

    protected getBanner(content: IMediaEventContent): JSX.Element {
        return null; // we don't need a banner, nor have space for one
    }

    render() {
        if (this.state.error) {
            return super.render();
        }

        const content = this.props.mxEvent.getContent<IMediaEventContent>();
        const thumbnail = this.messageContent(this.state.contentUrl, this.state.thumbUrl, content, FORCED_IMAGE_HEIGHT);
        const fileBody = this.getFileBody();
        const sender = <SenderProfile
            mxEvent={this.props.mxEvent}
        />;

        return <div className="mx_MImageReplyBody">
            { thumbnail }
            <div className="mx_MImageReplyBody_info">
                <div className="mx_MImageReplyBody_sender">{ sender }</div>
                <div className="mx_MImageReplyBody_filename">{ fileBody }</div>
            </div>
        </div>;
    }
}

} else if (this.context.timelineRenderingType === TimelineRenderingType.ThreadsList ||
    (this.context.timelineRenderingType === TimelineRenderingType.Thread && !this.props.continuation)
) {
    avatarSize = 32;
    needsSenderProfile = true;
} else if (eventType === EventType.RoomCreate || isBubbleMessage) {
    avatarSize = 0;
    needsSenderProfile = false;
} else if (this.props.layout == Layout.IRC) {
    avatarSize = 14;
    needsSenderProfile = true;
} else if (
    (this.props.continuation && this.context.timelineRenderingType !== TimelineRenderingType.File) ||
    eventType === EventType.CallInvite
) {
    // no avatar or sender profile for continuation messages and call tiles
    avatarSize = 0;
    needsSenderProfile = false;
} else {
    avatarSize = 30;
    needsSenderProfile = true;
}

if (this.props.mxEvent.sender && avatarSize) {
    let member;
    // set member to receiver (target) if it is a 3PID invite
    // so that the correct avatar is shown as the text is
    // `$target accepted the invitation for $email`
    if (this.props.mxEvent.getContent().third_party_invite) {
        member = this.props.mxEvent.target;
    } else {
        member = this.props.mxEvent.sender;
    }
    avatar = (
        <div className="mx_EventTile_avatar">
            <MemberAvatar
                member={member}
                width={avatarSize}
                height={avatarSize}
                viewUserOnClick={true}
                forceHistorical={this.props.mxEvent.getType() === EventType.RoomMember}
            />
        </div>
    );
}

if (needsSenderProfile && this.props.hideSender !== true) {
    if (this.context.timelineRenderingType === TimelineRenderingType.Room ||
        this.context.timelineRenderingType === TimelineRenderingType.Search ||
        this.context.timelineRenderingType === TimelineRenderingType.Pinned ||
        this.context.timelineRenderingType === TimelineRenderingType.Thread
    ) {
        sender = <SenderProfile
            onClick={this.onSenderProfileClick}
            mxEvent={this.props.mxEvent}
        />;
    } else {
        sender = <SenderProfile
            mxEvent={this.props.mxEvent}
        />;
    }
}

const showMessageActionBar = !isEditing && !this.props.forExport;
const actionBar = showMessageActionBar ? <MessageActionBar
    mxEvent={this.props.mxEvent}
    reactions={this.state.reactions}
    permalinkCreator={this.props.permalinkCreator}
    getTile={this.getTile}
    getReplyChain={this.getReplyChain}
    onFocusChange={this.onActionBarFocusChange}
    isQuoteExpanded={isQuoteExpanded}
    toggleThreadExpanded={() => this.setQuoteExpanded(!isQuoteExpanded)}
    getRelationsForEvent={this.props.getRelationsForEvent}
/> : undefined;

const showTimestamp = this.props.mxEvent.getTs()
    && (this.props.alwaysShowTimestamps
    || this.props.last
    || this.state.hover
    || this.state.actionBarFocused
const member = this.props.member;
const name = this.getDisplayName();
const presenceState = member.user ? member.user.presence : null;

const av = (
    <MemberAvatar member={member} width={36} height={36} aria-hidden="true" />
);

if (member.user) {
    this.userLastModifiedTime = member.user.getLastModifiedTime();
}
this.memberLastModifiedTime = member.getLastModifiedTime();

const powerStatusMap = new Map([
    [100, PowerStatus.Admin],
    [50, PowerStatus.Moderator],
]);

// Find the nearest power level with a badge
let powerLevel = this.props.member.powerLevel;
for (const [pl] of powerStatusMap) {
    if (this.props.member.powerLevel >= pl) {
        powerLevel = pl;
        break;
    }
}

const powerStatus = powerStatusMap.get(powerLevel);

let e2eStatus;
if (this.state.isRoomEncrypted) {
    e2eStatus = this.state.e2eStatus;
}

const nameJSX = (
    <DisambiguatedProfile
        member={member}
        fallbackName={name || ""}
    />
);

return (
    <EntityTile
        {...this.props}
        presenceState={presenceState}
        presenceLastActiveAgo={member.user ? member.user.lastActiveAgo : 0}
        presenceLastTs={member.user ? member.user.lastPresenceTs : 0}
        presenceCurrentlyActive={member.user ? member.user.currentlyActive : false}
        avatarJsx={av}
        title={this.getPowerLabel()}
        name={name}
        nameJSX={nameJSX}
        powerStatus={powerStatus}
        showPresence={this.props.showPresence}
        e2eStatus={e2eStatus}
        onClick={this.onClick}

